record={'type':'object','required':['id','kind','schemaVersion','revision','partitionId','updatedAt','accessClass','provenance'],'properties':{'id':string,'kind':string,'schemaVersion':{'type':'string','pattern':'^[0-9]+\\.[0-9]+\\.[0-9]+$'},'revision':{'type':'integer','minimum':0},'partitionId':string,'updatedAt':{'type':'string'},'accessClass':enum('gm-secret','gm','observer-private','party','published'),'provenance':list_of({'type':'object'})}}
def typ(kind,required,props):
 p={**record['properties'],'kind':{'const':kind},**props}
 return {'type':'object','required':list(record['required'])+required,'properties':p,'additionalProperties':False}
