Dct['TimeDue']=typ('time-due',['parentRecordId','dueAtWorldSeconds','duePolicy','prerequisitesRevision','currentStatus'],{'parentRecordId':string,'dueAtWorldSeconds':number,'duePolicy':enum('derived-expiration','conditional-action','gm-review'),'prerequisitesRevision':{'type':'integer','minimum':0},'currentStatus':enum('scheduled','due','pending-review','resolved','cancelled')})
