Dct['GraphActivation']=typ('graph-activation',['publishedSnapshotId','publishedRevision','state','authorityEpoch','lastValidatedAt'],{'publishedSnapshotId':string,'publishedRevision':string,'state':enum('inactive','active','suspended','archived'),'authorityEpoch':string,'lastValidatedAt':string,'activatedByEventId':string})
