Dct['ForesightFinding']=typ('foresight-finding',['generatedFromRevisionIds','boundedDependencies','findingType','status','createsCanonicalEvents'],{'generatedFromRevisionIds':list_of(string),'boundedDependencies':list_of(string),'findingType':enum('deadline','pressure','risk','opportunity','unresolved-choice'),'recommendedGMAction':string,'status':enum('fresh','stale','unverified'),'createsCanonicalEvents':{'const':False}})
