Dct['PublicNarrativeError']={'type':'object','required':['error'],'properties':{'error':enum('REQUEST_UNAVAILABLE','INVALID_PUBLIC_INPUT','ACTION_PENDING','ACTION_RESOLVED','RETRY_LATER'),'receiptId':string,'retryAfter':{'type':'integer','minimum':0}},'additionalProperties':False}
